// Charts use saved observations only. Missing timings are not converted to zero.
function timingValue(value) { return typeof value === 'number' && Number.isFinite(value) && value >= 0; }
function barChart(items, label, unit = 'ms') {
    if (!items.length) return '<p class="empty">No recorded measurements available. Run this project to collect evidence.</p>';
    const max = Math.max(1, ...items.map(item => item.value));
    const height = items.length * 46 + 25;
    return `<svg viewBox="0 0 760 ${height}" role="img" aria-label="${escape(label)}"><title>${escape(label)}. Each bar includes its exact value.</title>${items.map((item, i) => {
        const y = i * 46 + 10, width = item.value / max * 370;
        return `<text x="0" y="${y + 17}" font-size="14" fill="#263344">${escape(item.label.length > 27 ? item.label.slice(0,24) + '…' : item.label)}</text><rect x="235" y="${y}" width="370" height="24" rx="3" fill="#edf1f5"/><rect x="235" y="${y}" width="${width}" height="24" rx="3" fill="${item.color || '#126aa7'}"/><text x="617" y="${y + 17}" font-size="14" fill="#263344">${escape(item.value.toLocaleString(undefined,{maximumFractionDigits:2}))} ${escape(unit)}</text><title>${escape(item.label)}: ${escape(item.value)} ${escape(unit)}</title>`;
    }).join('')}</svg>`;
}
function analyticsHTML() {
    if (!selected) return '';
    const history = runs.filter(r => r.project === selected.id);
    const passed = history.filter(r => r.status === 'passed').length;
    const failed = history.filter(r => r.status === 'failed').length;
    const other = history.length - passed - failed;
    const timed = history.filter(r => timingValue(r.evidence?.engineDurationMs));
    const sorted = timed.map(r => r.evidence.engineDurationMs).sort((a,b)=>a-b);
    const median = sorted.length ? (sorted[Math.floor((sorted.length-1)/2)] + sorted[Math.floor(sorted.length/2)])/2 : null;
    const nodes = (record?.evidence?.nodeEvidence || []).filter(n => timingValue(n.durationMs));
    const recent = history.slice(0,8).reverse();
    return `<section class="panel analytics"><div class="eyebrow">Observed local data</div><h2>What happened in the demo</h2><p class="meta">${escape(selected.id)} · ${history.length} saved runs in the latest ${runs.length} portfolio records loaded (API limit: 100). This is a local sample, not production reliability or client ROI.</p><div class="metrics"><div class="metric"><strong>${passed}</strong><span>Passed runs</span></div><div class="metric"><strong>${failed}</strong><span>Failed runs</span></div><div class="metric"><strong>${median === null ? '—' : median.toLocaleString(undefined,{maximumFractionDigits:2}) + ' ms'}</strong><span>Median engine time · n=${timed.length}</span></div></div><div class="chart-grid"><figure><figcaption>Run outcomes · loaded sample</figcaption>${barChart([{label:'Passed',value:passed,color:'#08765d'},{label:'Failed',value:failed,color:'#a02f45'},...(other?[{label:'Other',value:other,color:'#925511'}]:[])],'Saved run outcomes','runs')}</figure><figure><figcaption>Recent engine times · oldest to newest</figcaption>${barChart(recent.filter(r=>timingValue(r.evidence?.engineDurationMs)).map(r=>({label:r.id,value:r.evidence.engineDurationMs,color:r.status==='passed'?'#126aa7':'#a02f45'})),'Recent saved engine durations')}<p class="meta">Latest eight runs considered; missing durations omitted. Failed runs with durations remain included.</p></figure></div><figure><figcaption>Selected run · n8n node durations</figcaption>${barChart(nodes.map(n=>({label:n.name,value:n.durationMs,color:n.status==='success'||n.status==='passed'?'#08765d':'#126aa7'})),'Selected run node durations')}<p class="meta">Run ${escape(record?.id || 'not selected')} · ${escape(stamp(record?.created))}. Node durations can overlap and are not a decomposition of total run time. Import/startup overhead is excluded from engine timing.</p></figure><details><summary>Inspect the chart data and timestamps</summary><div class="tablewrap"><table><thead><tr><th>Run / recorded at</th><th>Outcome</th><th>Engine ms</th><th>Full run ms</th></tr></thead><tbody>${history.map(r=>`<tr><td>${escape(r.id)}<br>${escape(stamp(r.created))}</td><td>${escape(r.status)}</td><td>${timingValue(r.evidence?.engineDurationMs)?escape(r.evidence.engineDurationMs):'Not recorded'}</td><td>${timingValue(r.evidence?.wallDurationMs)?escape(r.evidence.wallDurationMs):'Not recorded'}</td></tr>`).join('') || '<tr><td colspan="4">No saved runs.</td></tr>'}</tbody></table></div></details></section>`;
}
